import sqlite3
from sqlite3 import Error
from datetime import datetime
from pydantic import BaseModel, Field, model_validator
from typing import List

class RoomCreate(BaseModel):
    name: str
    capacity: int = Field(ge=1)

class Room(RoomCreate):
    id: int

class BookingCreate(BaseModel):
    room_id: int
    title: str = Field(min_length=1)
    start: datetime
    end: datetime

    @model_validator(mode='after')
    def validate_start_end(self):
        if self.start >= self.end:
            raise ValueError("start must be before end")
        return self

class Booking(BookingCreate):
    id: int

class NotFoundError(Exception):
    pass

class ConflictError(Exception):
    pass

class Storage:
    def __init__(self, db_path: str):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.cursor = self.conn.cursor()
        self.create_tables()

    def create_tables(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS rooms (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT UNIQUE,
                capacity INTEGER
            )
        ''')
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS bookings (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                room_id INTEGER,
                title TEXT,
                start TEXT,
                end TEXT,
                FOREIGN KEY (room_id) REFERENCES rooms(id)
            )
        ''')
        self.conn.commit()

    def create_room(self, data: RoomCreate) -> Room:
        try:
            self.cursor.execute('''
                INSERT INTO rooms (name, capacity) VALUES (?, ?)
            ''', (data.name, data.capacity))
            self.conn.commit()
            room_id = self.cursor.lastrowid
            return Room(id=room_id, **data.dict())
        except Error as e:
            raise ConflictError(f"Room name already taken: {e}")

    def get_room(self, room_id: int) -> Room:
        try:
            self.cursor.execute('''
                SELECT * FROM rooms WHERE id = ?
            ''', (room_id,))
            row = self.cursor.fetchone()
            if row:
                return Room(id=row[0], name=row[1], capacity=row[2])
            else:
                raise NotFoundError("Room not found")
        except Error as e:
            raise NotFoundError(f"Error retrieving room: {e}")

    def list_rooms(self) -> List[Room]:
        try:
            self.cursor.execute('''
                SELECT * FROM rooms ORDER BY name
            ''')
            rows = self.cursor.fetchall()
            return [Room(id=row[0], name=row[1], capacity=row[2]) for row in rows]
        except Error as e:
            raise NotFoundError(f"Error listing rooms: {e}")

    def create_booking(self, data: BookingCreate) -> Booking:
        try:
            self.cursor.execute('''
                SELECT * FROM rooms WHERE id = ?
            ''', (data.room_id,))
            room = self.cursor.fetchone()
            if not room:
                raise NotFoundError("Room not found")
            if self.check_overlap(data.start, data.end, room_id):
                raise ConflictError("Overlap with existing booking")
            self.cursor.execute('''
                INSERT INTO bookings (room_id, title, start, end) VALUES (?, ?, ?, ?)
            ''', (data.room_id, data.title, data.start.isoformat(), data.end.isoformat()))
            self.conn.commit()
            booking_id = self.cursor.lastrowid
            return Booking(id=booking_id, **data.dict())
        except Error as e:
            raise ConflictError(f"Error creating booking: {e}")

    def list_bookings(self, room_id: int) -> List[Booking]:
        try:
            self.cursor.execute('''
                SELECT * FROM bookings WHERE room_id = ? ORDER BY start
            ''', (room_id,))
            rows = self.cursor.fetchall()
            return [Booking(id=row[0], **row[1:]) for row in rows]
        except Error as e:
            raise NotFoundError(f"Error listing bookings: {e}")

    def delete_booking(self, booking_id: int) -> None:
        try:
            self.cursor.execute('''
                DELETE FROM bookings WHERE id = ?
            ''', (booking_id,))
            self.conn.commit()
        except Error as e:
            raise NotFoundError(f"Error deleting booking: {e}")

    def check_overlap(self, start: datetime, end: datetime, room_id: int) -> bool:
        self.cursor.execute('''
            SELECT * FROM bookings WHERE room_id = ? AND (start < ? AND end > ?) OR (start < ? AND end < ?) OR (start > ? AND end > ?)
        ''', (room_id, start, end, start, end, start, end))
        return self.cursor.fetchone() is not None
