from fastapi import FastAPI, HTTPException, Response
from fastapi.responses import JSONResponse
from pydantic import BaseModel, ValidationError
from booking.models import RoomCreate, Room, BookingCreate, Booking
from booking.storage import Storage, NotFoundError, ConflictError

app = FastAPI()

def create_app(db_path: str) -> FastAPI:
    storage = Storage(db_path)
    app.add_exception_handler(NotFoundError, handle_not_found)
    app.add_exception_handler(ConflictError, handle_conflict)
    return app

@app.get("/health")
def health():
    return {"status": "ok"}

@app.post("/rooms")
def create_room(data: RoomCreate):
    try:
        room = storage.create_room(data)
        return JSONResponse(status_code=201, content=room.dict())
    except ConflictError:
        raise HTTPException(status_code=409, detail="Room name already taken")

@app.get("/rooms")
def list_rooms():
    return JSONResponse(status_code=200, content=storage.list_rooms())

@app.post("/bookings")
def create_booking(data: BookingCreate):
    try:
        booking = storage.create_booking(data)
        return JSONResponse(status_code=201, content=booking.dict())
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Room not found")
    except ConflictError:
        raise HTTPException(status_code=409, detail="Overlap")

@app.get("/rooms/{room_id}/bookings")
def list_bookings(room_id: int):
    try:
        return JSONResponse(status_code=200, content=storage.list_bookings(room_id))
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Room not found")

@app.delete("/bookings/{booking_id}")
def delete_booking(booking_id: int):
    try:
        storage.delete_booking(booking_id)
        return Response(status_code=204)
    except NotFoundError:
        raise HTTPException(status_code=404, detail="Booking not found")

def handle_not_found(exc: NotFoundError):
    return JSONResponse(status_code=404, content={"detail": exc.detail})

def handle_conflict(exc: ConflictError):
    return JSONResponse(status_code=409, content={"detail": exc.detail})
